28	public abstract class BasicFuseableObserver<T, R> implements Observer<T>, QueueDisposable<R> {
29	
30	    /** The downstream subscriber. */
31	    protected final Observer<? super R> downstream;
32	
33	    /** The upstream subscription. */
34	    protected Disposable upstream;
35	
36	    /** The upstream's QueueDisposable if not null. */
37	    protected QueueDisposable<T> qd;
38	
39	    /** Flag indicating no further onXXX event should be accepted. */
40	    protected boolean done;
41	
42	    /** Holds the established fusion mode of the upstream. */
43	    protected int sourceMode;
44	
45	    /**
46	     * Construct a BasicFuseableObserver by wrapping the given subscriber.
47	     * @param downstream the subscriber, not null (not verified)
48	     */
49	    public BasicFuseableObserver(Observer<? super R> downstream) {
50	        this.downstream = downstream;
51	    }
52	
53	    // final: fixed protocol steps to support fuseable and non-fuseable upstream
54	    @SuppressWarnings("unchecked")
55	    @Override
56	    public final void onSubscribe(Disposable d) {
57	        if (DisposableHelper.validate(this.upstream, d)) {
58	
59	            this.upstream = d;
60	            if (d instanceof QueueDisposable) {
61	                this.qd = (QueueDisposable<T>)d;
62	            }
63	
64	            if (beforeDownstream()) {
65	
66	                downstream.onSubscribe(this);
67	
68	                afterDownstream();
69	            }
70	
71	        }
72	    }
