74	    /**
75	     * Override this to perform actions before the call {@code actual.onSubscribe(this)} happens.
76	     * @return true if onSubscribe should continue with the call
77	     */
78	    protected boolean beforeDownstream() {
79	        return true;
80	    }
81	
82	    /**
83	     * Override this to perform actions after the call to {@code actual.onSubscribe(this)} happened.
84	     */
85	    protected void afterDownstream() {
86	        // default no-op
87	    }
88	
89	    // -----------------------------------
90	    // Convenience and state-aware methods
91	    // -----------------------------------
92	
93	    @Override
94	    public void onError(Throwable t) {
95	        if (done) {
96	            RxJavaPlugins.onError(t);
97	            return;
98	        }
99	        done = true;
100	        downstream.onError(t);
101	    }
102	
103	    /**
104	     * Rethrows the throwable if it is a fatal exception or calls {@link #onError(Throwable)}.
105	     * @param t the throwable to rethrow or signal to the actual subscriber
