156	    public boolean isDisposed() {
157	        return upstream.isDisposed();
158	    }
159	
160	    @Override
161	    public boolean isEmpty() {
162	        return qd.isEmpty();
163	    }
164	
165	    @Override
166	    public void clear() {
167	        qd.clear();
168	    }
169	
170	    // -----------------------------------------------------------
171	    // The rest of the Queue interface methods shouldn't be called
172	    // -----------------------------------------------------------
173	
174	    @Override
175	    public final boolean offer(R e) {
176	        throw new UnsupportedOperationException("Should not be called!");
177	    }
