34	    static final class OnErrorReturnObserver<T> implements Observer<T>, Disposable {
35	        final Observer<? super T> downstream;
36	        final Function<? super Throwable, ? extends T> valueSupplier;
37	
38	        Disposable upstream;
39	
40	        OnErrorReturnObserver(Observer<? super T> actual, Function<? super Throwable, ? extends T> valueSupplier) {
41	            this.downstream = actual;
42	            this.valueSupplier = valueSupplier;
43	        }
44	
45	        @Override
46	        public void onSubscribe(Disposable d) {
47	            if (DisposableHelper.validate(this.upstream, d)) {
48	                this.upstream = d;
49	                downstream.onSubscribe(this);
50	            }
51	        }
52	
53	        @Override
54	        public void dispose() {
55	            upstream.dispose();
56	        }
57	
58	        @Override
59	        public boolean isDisposed() {
60	            return upstream.isDisposed();
61	        }
